import csv,json
from pathlib import Path
from etymology_assignments import read_assignments
P=Path('curation/etymology-lab/indo-aryan-diversity-20260922');linked={r['Form_ID'] for r in read_assignments() if r['Status']=='accepted'};linked.update(r['Child_ID'] for r in csv.DictReader(open('cldf/edges.csv')) if r['Rank']=='1')
rs=[r for r in csv.DictReader(open('cldf/forms.csv')) if 'buddruss-grangali1979[' in r['Source'] and r['ID'] not in linked]
groups=[('hear',['ṣū́r','śuni'],'12598','śṛṇoti','Buddruss p28 item50 explicitly derives Grangali ṣūr from *śrun-, compares the Ashokan śruṇeyu type and insists on the source retroflex sibilant. Turner12598 directly gives Ningalam šuni and Shumashti šūne. The prefixless hear family is selected, not āśṛṇoti1460; source r and sibilants remain unchanged.'),('eat',['xo','xuy'],'3865','khādati','Buddruss p31 item87 explicitly identifies Grangali xo/xoa and Ningalam xuy as continuations of khāda-. Turner3865 directly lists Ningalam xuy under the present stem, distinct from the khādita past, causative and passive branches.'),('house',['gē'],'4251','geha','Buddruss p31 item86 explicitly identifies the Grangali/Ningalam house word with Sanskrit geha and corrects an alleged Waigali comparison. Turner4251 directly gives Ningalam gē. This is the specific geha family, whose deeper relation to gṛha is questioned by Turner.'),('mirror',['arṣə́'],'1143','ādarśa','Buddruss p31 item88 explicitly derives Grangali arṣə from Middle Indo-Aryan *ādariṣa and compares Prakrit ādarisa and Shumashti reṣə. Turner1143 independently gives the expanded MIA *ādariśa family, including Shumashti reṣe with ṣ explicitly noted.'),('black',['kāʦá','xaʦə'],'3008','*kāca²','Turner3008 explicitly lists Ningalam kāċə and Shumashti xaċə black under *kāca², noting Shumashti x from kh. Buddruss p31 item94 confirms those comparisons but leaves the k/kh history unresolved. Retain that uncertainty: this existing family assignment does not claim that the consonant alternation is explained. Grangali nasal kānʦə is excluded pending further analysis.')]
a=[];lines=['# Grangali survey: hearing, eating and household vocabulary','','Eight proposed reflex records across five families; standing autonomous authorization.','','| # | Forms and meanings | Proposed etymology | Evidence |','|---|---|---|---|']
for i,(g,forms,parent,label,ev) in enumerate(groups,1):
 hits=[r for r in rs if r['Form'] in forms and r['Gloss']==g];assert len(hits)==len(forms),(g,len(hits))
 for r in hits:a.append(dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},parent=parent,kind='reflex',citation=r['Source']+';CDIAL['+parent+' and addenda]',evidence=ev+' Existing manual source collation and source image checked; no transcription or identity repair.'))
 lines.append(f'| {i} | **{" / ".join(forms)}** ‘{g}’ ({len(hits)} records) | **{label}**, CDIAL **{parent}** | {ev} |')
h=[dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},reason='Grangali kānʦə black is compared with the kāca family, but its nasal and the unresolved k/kh history require a more specific account before assignment.') for r in rs if r['Form']=='kānʦə́' and r['Gloss']=='black']
assert len(a)==8
(P/'pass047-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=2)+'\n')
sources={x['record']['Source'] for x in a+h};audit=[r for r in csv.DictReader(open('data/other/forms/raw_data/20260819-buddruss-grangali-audit.csv')) if r['Source'] in sources];assert all(r['Material_Error']=='no' for r in audit)
(P/'pass047-source-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
lines+=['','One Grangali black record held. Research: homepage grangali-search013; complete articles/addenda grangali-primary010. Existing images render/page-12.png and page-15.png correspond to printed28 and31; source audit retained.','Validation: pending.'];(P/'pass047-review.md').write_text('\n'.join(lines)+'\n');print(len(a),'accepted',len(h),'held')
